import { FrameworkErrorCode, serializeJsonValue } from "@mit-sdg/sync-engine/boundary";
const RESERVED_RESPONSE_HEADERS = new Set([
    "cache-control",
    "connection",
    "content-encoding",
    "content-length",
    "content-type",
    "keep-alive",
    "location",
    "proxy-connection",
    "refresh",
    "set-cookie",
    "te",
    "trailer",
    "transfer-encoding",
    "upgrade",
    "vary",
]);
export function isReservedResponseHeader(name) {
    const lower = name.toLowerCase();
    return RESERVED_RESPONSE_HEADERS.has(lower) || lower.startsWith("access-control-");
}
export function internalErrorResponse() {
    return new Response(`{"error":"${FrameworkErrorCode.INTERNAL_ERROR}"}`, {
        status: 500,
        headers: { "Content-Type": "application/json" },
    });
}
export function publicJson(body, status, options = {}) {
    try {
        const headers = new Headers({ "Content-Type": "application/json" });
        for (const cookie of options.cookies ?? [])
            headers.append("Set-Cookie", cookie);
        if (options.noStore === true)
            headers.set("Cache-Control", "no-store");
        return new Response(serializeJsonValue(body), { status, headers });
    }
    catch {
        return internalErrorResponse();
    }
}
export async function withResponseHeaders(response, option, context) {
    if (option === undefined)
        return response;
    try {
        const source = typeof option === "function" ? await option(context) : option;
        for (const [name, value] of new Headers(source)) {
            if (!isReservedResponseHeader(name))
                response.headers.set(name, value);
        }
        return response;
    }
    catch {
        return undefined;
    }
}
